new_telegram_case = '''  telegram)\n    case "${2:-}" in\n      identity)\n        case "${3:-status}" in\n          status) exec "$MANAGER_HOME/modules/telegram_identity.sh" --status ;;\n          list) exec "$MANAGER_HOME/modules/telegram_identity.sh" --list ;;\n          show) [[ -n "${4:-}" ]] || { err "Uso: manager telegram identity show TELEGRAM_USER_ID"; exit 64; }; exec "$MANAGER_HOME/modules/telegram_identity.sh" --show "$4" ;;\n          bind) [[ -n "${4:-}" && -n "${5:-}" ]] || { err "Uso: manager telegram identity bind TELEGRAM_USER_ID PRINCIPAL_ID"; exit 64; }; exec "$MANAGER_HOME/modules/telegram_identity.sh" --bind "$4" "$5" ;;\n          enable) [[ -n "${4:-}" ]] || { err "Uso: manager telegram identity enable TELEGRAM_USER_ID"; exit 64; }; exec "$MANAGER_HOME/modules/telegram_identity.sh" --enable "$4" ;;\n          disable) [[ -n "${4:-}" ]] || { err "Uso: manager telegram identity disable TELEGRAM_USER_ID"; exit 64; }; exec "$MANAGER_HOME/modules/telegram_identity.sh" --disable "$4" ;;\n          resolve) [[ -n "${4:-}" ]] || { err "Uso: manager telegram identity resolve TELEGRAM_USER_ID"; exit 64; }; exec "$MANAGER_HOME/modules/telegram_identity.sh" --resolve "$4" ;;\n          *) err "Uso: manager telegram identity {status|list|show|bind|enable|disable|resolve} ..."; exit 64 ;;\n        esac\n        ;;\n      auth)\n        case "${3:-status}" in\n          status) exec "$MANAGER_HOME/modules/telegram_auth.sh" --status ;;\n          token)\n            case "${4:-}" in\n              install) [[ -n "${5:-}" ]] || { err "Uso: manager telegram auth token install /CAMINHO/BOT_TOKEN"; exit 64; }; exec "$MANAGER_HOME/modules/telegram_auth.sh" --token-install "$5" ;;\n              *) err "Uso: manager telegram auth token install /CAMINHO/BOT_TOKEN"; exit 64 ;;\n            esac\n            ;;\n          freshness)\n            case "${4:-}" in\n              set) [[ -n "${5:-}" ]] || { err "Uso: manager telegram auth freshness set MAX_AGE_SECONDS [FUTURE_SKEW_SECONDS]"; exit 64; }; exec "$MANAGER_HOME/modules/telegram_auth.sh" --freshness-set "$5" "${6:-30}" ;;\n              *) err "Uso: manager telegram auth freshness set MAX_AGE_SECONDS [FUTURE_SKEW_SECONDS]"; exit 64 ;;\n            esac\n            ;;\n          verify) [[ -n "${4:-}" ]] || { err "Uso: manager telegram auth verify /CAMINHO/INITDATA"; exit 64; }; exec "$MANAGER_HOME/modules/telegram_auth.sh" --verify "$4" ;;\n          verify-stdin) exec "$MANAGER_HOME/modules/telegram_auth.sh" --verify-stdin ;;\n          resolve) [[ -n "${4:-}" ]] || { err "Uso: manager telegram auth resolve /CAMINHO/INITDATA"; exit 64; }; exec "$MANAGER_HOME/modules/telegram_auth.sh" --resolve "$4" ;;\n          resolve-stdin) exec "$MANAGER_HOME/modules/telegram_auth.sh" --resolve-stdin ;;\n          *) err "Uso: manager telegram auth {status|token|freshness|verify|verify-stdin|resolve|resolve-stdin} ..."; exit 64 ;;\n        esac\n        ;;\n      *) err "Uso: manager telegram {identity|auth} ..."; exit 64 ;;\n    esac\n    ;;'''
